using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
namespace QuietDread {
[Serializable] public class ChronicleUnit {public string id,type,name;public int team,army,hp,startHP,xp,rank,kills;public bool temporary,titan,commander;}
[Serializable] public class ChronicleProvince {public int id,tier;public string name,owner,buildings;}
[Serializable] public class ChronicleState {public int turn,act,gold,army;public string phase,status,commander,positions,decision;public List<ChronicleUnit> units=new List<ChronicleUnit>();public List<ChronicleProvince> provinces=new List<ChronicleProvince>();}
[Serializable] public class ChronicleEvent {
 public string strategicContext,territoryBefore,territoryAfter;public string id,kind,utc,mode,faction,commander,location,opponent,outcome="none",facts,text,source="Authored fallback",generation="pending",thread="remember_fallen";
 public int number,turn,act,army,goldBefore,goldAfter,playerScore,enemyScore;public bool commanderLost,estimatedStart;
 public List<ChronicleUnit> forces=new List<ChronicleUnit>();public string[] changes=new string[0];
 public string[] Lost(){return forces.Where(u=>u.team==0&&!u.temporary&&u.hp<=0).Select(u=>u.id).OrderBy(s=>s).ToArray();}
 public string[] Survived(){return forces.Where(u=>u.team==0&&!u.temporary&&u.hp>0).Select(u=>u.id).OrderBy(s=>s).ToArray();}
}
public partial class Campaign {
 public string lastChronicleChoice;
 public bool Choice(string choice){bool ok=ChoiceCore(choice);if(ok)lastChronicleChoice="Trail decision: "+choice;return ok;}
 public bool Capture(bool raze){bool ok=CaptureCore(raze);if(ok)lastChronicleChoice=raze?"Razed the conquered settlement":"Occupied the conquered settlement";return ok;}
 public Battle BattleForSave(Battle b){return phase=="battle"&&b!=null&&b.chronicleCampaignId==chronicleId&&b.campaignBattleId==pendingId&&!settled?b:null;}
 public string chronicleId;public int chronicleSequence,archivedEntries,totalRecordedLosses;public string chronicleMemory="";public ChronicleState chronicleState;public List<ChronicleEvent> journal=new List<ChronicleEvent>();
 public void EnsureChronicle(){if(string.IsNullOrEmpty(chronicleId))chronicleId=Guid.NewGuid().ToString("N");if(journal==null)journal=new List<ChronicleEvent>();if(chronicleMemory==null)chronicleMemory="";}
 public ChronicleState ChronicleSnapshot(){var s=new ChronicleState{turn=turn,act=act,gold=gold,army=selectedArmy,phase=phase,status=status,commander=commanderId,decision=lastChronicleChoice,positions=string.Join("; ",armies.Select(a=>"Army "+a.id+" at region "+a.region+(a.moved?" (moved)":"")))};foreach(var a in armies)foreach(var u in a.units){var p=data.P(u.type);s.units.Add(new ChronicleUnit{id=u.id,type=u.type,name=p.name,army=a.id,hp=u.hp,startHP=u.hp,xp=u.xp,rank=u.level,commander=p.commander,titan=p.titan});}foreach(var p in provinces)s.provinces.Add(new ChronicleProvince{id=p.id,name=p.name,owner=p.owner,tier=p.tier,buildings=string.Join(", ",p.buildings)});return s;}
 string StrategicChronicleContext(){return mode=="trail"?"Act "+act+" of 3; campaign "+status:"Campaign "+status+". Regions: "+string.Join("; ",provinces.Select(p=>p.name+"="+(p.owner==""?"unclaimed":p.owner)))+". Armies: "+string.Join("; ",armies.Select(a=>a.id+" at "+provinces[a.region].name+", formations "+a.units.Count));}
 ChronicleEvent NewChronicleEvent(string kind){EnsureChronicle();return new ChronicleEvent{kind=kind,strategicContext=StrategicChronicleContext(),mode=mode,faction=data.F(faction).name,commander=commanderId,turn=turn,act=act,army=selectedArmy,goldBefore=gold,goldAfter=gold,location=mode=="trail"?"Trail act "+act+", encounter "+(pendingRow+1):Army!=null?provinces[Army.region].name:"Frontier",utc=DateTime.UtcNow.ToString("O")};}
 public void AppendChronicle(ChronicleEvent e){EnsureChronicle();if(!string.IsNullOrEmpty(e.id)&&journal.Any(x=>x.id==e.id))return;e.number=++chronicleSequence;if(string.IsNullOrEmpty(e.id))e.id=chronicleId+":"+e.number;e.facts=NarrativeText.Facts(e)+(e.mode=="conquest"&&e.kind=="battle"?"\nTerritory owner: "+(string.IsNullOrEmpty(e.territoryBefore)?"unclaimed":e.territoryBefore)+" → "+(string.IsNullOrEmpty(e.territoryAfter)?"unclaimed":e.territoryAfter):"");e.text=NarrativeText.Fallback(e);e.thread=e.Lost().Length>0?"remember_fallen":journal.LastOrDefault()?.thread??(mode=="trail"?"reach_sentinel":"secure_frontier");journal.Add(e);totalRecordedLosses+=e.Lost().Length;while(journal.Count>120){journal.RemoveAt(0);archivedEntries++;}chronicleMemory="Recorded permanent formation losses: "+totalRecordedLosses+". Earlier entries archived: "+archivedEntries+".\n"+string.Join("\n",journal.Skip(Math.Max(0,journal.Count-4)).Select(x=>NarrativeText.Limit(x.facts,450)));}
 public void ObserveChronicle(){EnsureChronicle();var now=ChronicleSnapshot();if(chronicleState==null){var intro=NewChronicleEvent(chronicleSequence==0?"introduction":"continuation");intro.forces=now.units;intro.changes=new[]{"Campaign status: "+status,"Existing campaign history before this journal is not reconstructed."};AppendChronicle(intro);chronicleState=now;return;}
  var before=chronicleState;var changes=new List<string>();if(before.decision!=now.decision&&!string.IsNullOrEmpty(now.decision))changes.Add(now.decision);if(before.positions!=now.positions)changes.Add("Positions: "+now.positions);if(before.act!=now.act)changes.Add("Act "+before.act+" → "+now.act);if(before.turn!=now.turn)changes.Add("Strategic turn "+before.turn+" → "+now.turn);if(before.phase!=now.phase)changes.Add("Phase "+before.phase+" → "+now.phase);if(before.status!=now.status)changes.Add("Campaign status "+before.status+" → "+now.status);if(before.gold!=now.gold)changes.Add("Gold "+before.gold+" → "+now.gold);
  foreach(var u in now.units){var old=before.units.FirstOrDefault(v=>v.id==u.id);if(old==null)changes.Add("Recruited "+u.name+" ["+u.id+"] into army "+u.army);else{if(old.hp!=u.hp)changes.Add(u.name+" ["+u.id+"] HP "+old.hp+" → "+u.hp);if(old.rank!=u.rank||old.xp!=u.xp)changes.Add(u.name+" ["+u.id+"] rank "+u.rank+", XP "+u.xp);if(old.army!=u.army)changes.Add(u.id+" transferred to army "+u.army);}}
  foreach(var p in now.provinces){var old=before.provinces.FirstOrDefault(q=>q.id==p.id);if(old!=null&&(p.owner!=old.owner||p.tier!=old.tier||p.buildings!=old.buildings))changes.Add(p.name+": owner "+(old.owner==""?"unclaimed":old.owner)+" → "+(p.owner==""?"unclaimed":p.owner)+"; tier "+p.tier+"; buildings "+p.buildings);}
  foreach(var a in armies){var old=before.units.FirstOrDefault(u=>u.army==a.id);if(mode=="conquest")changes.Add("Army "+a.id+" at "+provinces[a.region].name+"; "+a.units.Count+" formations");}
  // Do not manufacture events for selecting an army, opening a journal or repeated saves.
  bool changed=JsonUtility.ToJson(before)!=JsonUtility.ToJson(now);if(changed&&!(changes.All(x=>x.StartsWith("Army ")))){var e=NewChronicleEvent(now.status!="active"?"ending":before.act!=now.act?"act transition":"campaign decision");e.goldBefore=before.gold;e.goldAfter=gold;e.forces=now.units;e.changes=changes.ToArray();AppendChronicle(e);}chronicleState=now;
 }
 public bool Settle(Battle b){if(b==null||!b.finished||settled||b.campaignBattleId!=pendingId||Army==null)return false;EnsureChronicle();if(chronicleState==null)ObserveChronicle();var e=NewChronicleEvent("battle");e.id=chronicleId+":battle:"+b.campaignBattleId;e.location=mode=="trail"?"Trail act "+act+", "+eventKind+" encounter "+(pendingRow+1):provinces[attackTarget].name;e.opponent=data.F(b.factions[1]).name;e.outcome=b.winner==0?"victory":b.winner==1?"defeat":"draw";e.playerScore=b.score[0];e.enemyScore=b.score[1];
  foreach(var u in b.units){var p=data.P(u.type);var start=b.chronicleStart?.FirstOrDefault(x=>x.id==(string.IsNullOrEmpty(u.persistentId)?"battle-"+u.id:u.persistentId));var veteran=Army.units.FirstOrDefault(v=>v.id==u.persistentId);if(start==null&&!u.spawned)e.estimatedStart=true;e.forces.Add(new ChronicleUnit{id=string.IsNullOrEmpty(u.persistentId)?"battle-"+u.id:u.persistentId,type=u.type,name=p.name,team=u.team,army=u.team==0?Army.id:0,hp=u.hp,startHP=start!=null?start.hp:veteran!=null?veteran.hp:p.hp+u.level*3,rank=u.level,xp=u.xp,kills=u.kills,temporary=u.spawned,titan=p.titan,commander=p.commander});}
  e.commanderLost=e.forces.Any(u=>u.id==commanderId&&u.hp<=0);int province=attackTarget;if(mode=="conquest")e.territoryBefore=provinces[province].owner;bool success=SettleCore(b);if(mode=="conquest")e.territoryAfter=provinces[province].owner;if(!success)return false;e.goldAfter=gold;e.strategicContext=StrategicChronicleContext();foreach(var u in e.forces){var v=armies.SelectMany(a=>a.units).FirstOrDefault(q=>q.id==u.id);if(v!=null){u.xp=v.xp;u.rank=v.level;}}e.changes=new[]{"Campaign status: "+status,"Next phase: "+phase,message};AppendChronicle(e);chronicleState=ChronicleSnapshot();if(status!="active"){var end=NewChronicleEvent("ending");end.changes=new[]{"Campaign status: "+status,"Original commander lost: "+e.commanderLost};AppendChronicle(end);}return true;
 }
}
public partial class Battle {public string chronicleCampaignId;public List<ChronicleUnit> chronicleStart;public void CaptureChronicleStart(){chronicleStart=units.Select(u=>new ChronicleUnit{id=string.IsNullOrEmpty(u.persistentId)?"battle-"+u.id:u.persistentId,hp=u.hp}).ToList();}}
public static class NarrativeText {
 public static string Limit(string s,int n){return string.IsNullOrEmpty(s)?"":s.Length<=n?s:s.Substring(0,n);}
 public static string Facts(ChronicleEvent e){return e.kind.ToUpperInvariant()+" · "+e.location+" · Army "+e.army+"\n"+e.faction+(string.IsNullOrEmpty(e.opponent)?"":" vs "+e.opponent)+"\nOutcome: "+e.outcome+". Relay score "+e.playerScore+" : "+e.enemyScore+".\nPermanent formations lost: "+e.Lost().Length+"; survivors: "+e.Survived().Length+". Original commander lost: "+e.commanderLost+".\nGold: "+e.goldBefore+" → "+e.goldAfter+"\n"+string.Join("\n",e.changes??new string[0]);}
 public static string Fallback(ChronicleEvent e){if(e.kind=="introduction")return e.mode=="trail"?"The expedition gathers at the edge of the silent road. Every formation carries a place in the line; every return will be counted. Beyond the first encounter, the sentinels wait.":"Across the frontier, isolated relays still answer. The campaign begins with a command, an army and the settlements recorded below. Holding them will demand more than a single victory.";if(e.kind=="ending")return "The campaign reaches its recorded conclusion. Its ledger preserves the choices and the cost; the journal will not rewrite them.";if(e.kind=="act transition")return "Another stretch of the road opens. Those who remain carry the memory of the earlier march into the next act.";if(e.kind=="battle")return (e.outcome=="victory"?"The field has been won.":e.outcome=="draw"?"The field yields no decisive victor.":"The field has been lost.")+(e.commanderLost?" The original commander's formation is among the fallen.":"")+(e.Lost().Length>0?" Empty places in the permanent ranks give the result its weight.":" The permanent ranks suffered no destroyed formations in this engagement.")+(e.mode=="trail"?" The expedition's next step is recorded below.":" The wider war continues according to the campaign ledger.");return "The campaign ledger changes. Supplies, positions and the condition of the formations shape what can follow. The recorded decisions below are the history that matters.";}
}
}
